export function traceLot(lot,direction='both'){const matches=traceNodes.filter(n=>n.lot===lot),roots=matches.filter(n=>n.kind==='P'?n.type==='produce':n.type==='receive'),anchors=(roots.length?roots:matches).map(n=>n.id);if(!anchors.length)return {nodes:[],edges:[],deliveries:[],lots:[]};const ids=new Set(anchors);function walk(reverse){const seen=new Set(anchors),queue=[...anchors];while(queue.length){const id=queue.shift();for(const [a,b] of traceEdges){const source=reverse?b:a,target=reverse?a:b;if(source===id&&!seen.has(target)){seen.add(target);ids.add(target);queue.push(target);}}}}if(direction!=='down')walk(true);if(direction!=='up')walk(false);const nodes=traceNodes.filter(n=>ids.has(n.id));return {nodes,edges:traceEdges.filter(([a,b])=>ids.has(a)&&ids.has(b)),deliveries:nodes.filter(n=>n.type==='deliver'),lots:[...new Set(nodes.filter(n=>n.type==='produce').map(n=>n.lot))]};}
